"""Results page showing simulation outputs and plots."""

from __future__ import annotations

import json
import sys
import time
from dataclasses import dataclass
from pathlib import Path
from typing import Callable

import pandas as pd
import streamlit as st

from dashboard.app import (
    _DEF_XLSX,
    PLOTS,
    _get_plot_fn,
    apply_theme,
    load_data,
    render_settings_sidebar,
)
from dashboard.browser_exports import render_async_export_button, render_png_download
from dashboard.components.comparison_llm import render_comparison_llm_panel
from dashboard.components.explain_results import render_explain_results_panel
from dashboard.glossary import tooltip
from dashboard.utils import RESULTS_EMPTY_STATE_MESSAGE, current_results_path
from pa_core.contracts import (
    SUMMARY_AGENT_COLUMN,
    SUMMARY_ANN_RETURN_COLUMN,
    SUMMARY_BREACH_PROB_COLUMN,
    SUMMARY_CVAR_COLUMN,
    SUMMARY_SHEET_NAME,
    SUMMARY_TE_COLUMN,
    SUMMARY_TRACKING_ERROR_LEGACY_COLUMN,
    manifest_path_for_output,
)
from pa_core.llm.compare_runs import load_prior_manifest, load_prior_summary


@dataclass(frozen=True)
class _PreviousRunAvailability:
    available: bool
    prior_manifest_path: Path | None
    message: str | None


def _prior_output_path(prior_manifest: dict | None, prior_manifest_path: Path) -> Path | None:
    cli_args = prior_manifest.get("cli_args") if isinstance(prior_manifest, dict) else None
    if not isinstance(cli_args, dict):
        return None
    output = cli_args.get("output")
    if not isinstance(output, str) or not output.strip():
        return None
    output_path = Path(output).expanduser()
    if not output_path.is_absolute():
        output_path = prior_manifest_path.expanduser().parent / output_path
    return output_path


def _check_previous_run_availability(
    manifest_data: dict | None,
) -> _PreviousRunAvailability:
    """Check whether ``manifest_data['previous_run']`` points to a readable manifest."""

    if not isinstance(manifest_data, dict):
        return _PreviousRunAvailability(
            available=False,
            prior_manifest_path=None,
            message=(
                "Comparison unavailable: missing artifact `manifest_data['previous_run']`. "
                "Expected file path to prior `manifest.json` in the current manifest."
            ),
        )

    prev_ref = manifest_data.get("previous_run")
    expected_path = (
        str(Path(prev_ref).expanduser())
        if isinstance(prev_ref, str) and prev_ref.strip()
        else "<unset>"
    )

    try:
        prior_manifest, prior_manifest_path = load_prior_manifest(manifest_data)
    except Exception as exc:
        return _PreviousRunAvailability(
            available=False,
            prior_manifest_path=Path(expected_path) if expected_path != "<unset>" else None,
            message=(
                "Comparison unavailable: unreadable artifact `manifest_data['previous_run']` "
                f"at expected file path `{expected_path}` ({exc})."
            ),
        )

    if prior_manifest is not None and prior_manifest_path is not None:
        try:
            prior_summary, prior_summary_path = load_prior_summary(
                prior_manifest, manifest_path=prior_manifest_path
            )
        except Exception as exc:
            expected_summary = _prior_output_path(prior_manifest, prior_manifest_path)
            expected_summary_text = str(expected_summary) if expected_summary else "<unset>"
            return _PreviousRunAvailability(
                available=False,
                prior_manifest_path=prior_manifest_path,
                message=(
                    "Comparison unavailable: unreadable prior output workbook referenced by "
                    f"`manifest_data['previous_run']`; expected output file "
                    f"`{expected_summary_text}` ({exc})."
                ),
            )
        if prior_summary is None:
            expected_summary = str(prior_summary_path) if prior_summary_path else "<unset>"
            missing_target = (
                "prior output workbook"
                if prior_summary_path is not None
                else "`cli_args.output` path in the prior manifest"
            )
            return _PreviousRunAvailability(
                available=False,
                prior_manifest_path=prior_manifest_path,
                message=(
                    f"Comparison unavailable: missing {missing_target} referenced by "
                    f"`manifest_data['previous_run']`; expected output file `{expected_summary}`."
                ),
            )
        return _PreviousRunAvailability(
            available=True,
            prior_manifest_path=prior_manifest_path,
            message=None,
        )

    if prior_manifest_path is None:
        return _PreviousRunAvailability(
            available=False,
            prior_manifest_path=None,
            message=(
                "Comparison unavailable: missing artifact `manifest_data['previous_run']`. "
                "Expected file path to prior `manifest.json` in the current manifest."
            ),
        )

    return _PreviousRunAvailability(
        available=False,
        prior_manifest_path=prior_manifest_path,
        message=(
            "Comparison unavailable: missing artifact `manifest_data['previous_run']` "
            f"at expected file path `{prior_manifest_path}`."
        ),
    )


def _render_explain_results(
    *, summary: pd.DataFrame, manifest_data: dict | None, xlsx: str
) -> None:
    try:
        render_explain_results_panel(summary_df=summary, manifest=manifest_data, xlsx_path=xlsx)
    except ModuleNotFoundError:
        st.info("LLM features unavailable. Install .[llm] to enable Explain Results.")
    except Exception:
        st.info("LLM features unavailable. Install .[llm] to enable Explain Results.")


def _render_comparison_panel(
    *,
    summary: pd.DataFrame,
    manifest_data: dict | None,
    xlsx: str,
    render_panel: Callable[..., None] = render_comparison_llm_panel,
) -> _PreviousRunAvailability:
    """Render comparison panel or a specific availability message."""

    st.subheader("LLM Comparison")
    availability = _check_previous_run_availability(manifest_data)
    if availability.available and availability.prior_manifest_path is not None:
        run_key = f"{Path(xlsx).resolve()}::{availability.prior_manifest_path.resolve()}"
        render_panel(summary_df=summary, manifest_data=manifest_data, run_key=run_key)
    elif availability.message:
        st.info(availability.message)
    return availability


def _default_results_path() -> str:
    """Return the in-session wizard output path or the legacy default workbook."""
    return current_results_path(st.session_state) or _DEF_XLSX


def _overlay_total_return(summary: pd.DataFrame) -> float | None:
    if {SUMMARY_AGENT_COLUMN, SUMMARY_ANN_RETURN_COLUMN} <= set(summary.columns):
        total_rows = summary[summary[SUMMARY_AGENT_COLUMN] == "Total"]
        if not total_rows.empty:
            return float(total_rows[SUMMARY_ANN_RETURN_COLUMN].mean())
    return None


def main() -> None:
    st.title("Results")
    xlsx, theme_path = render_settings_sidebar(_default_results_path())
    apply_theme(theme_path)
    if not Path(xlsx).exists():
        st.info(RESULTS_EMPTY_STATE_MESSAGE)
        st.stop()
    summary, paths = load_data(xlsx)

    # Load manifest if available for display and export embedding
    manifest_data = None
    manifest_path = manifest_path_for_output(xlsx)
    if manifest_path.exists():
        try:
            manifest_data = json.loads(manifest_path.read_text())
            seed = manifest_data.get("seed")
            if seed is not None:
                st.caption(f"Seed: {seed}")
        except Exception:
            manifest_data = None

    months = st.sidebar.slider("Months", 1, summary.shape[0], summary.shape[0])

    st.subheader("Key Metrics")
    col1, col2, col3, col4 = st.columns(4)
    te_column = None
    if SUMMARY_TE_COLUMN in summary:
        te_column = SUMMARY_TE_COLUMN
    elif SUMMARY_TRACKING_ERROR_LEGACY_COLUMN in summary:
        te_column = SUMMARY_TRACKING_ERROR_LEGACY_COLUMN
    if te_column is not None:
        col1.metric(
            "Tracking Error", f"{summary[te_column].mean():.2%}", help=tooltip("monthly_TE")
        )
    if SUMMARY_CVAR_COLUMN in summary:
        col2.metric(
            "monthly_CVaR",
            f"{summary[SUMMARY_CVAR_COLUMN].mean():.2%}",
            help=tooltip("monthly_CVaR"),
        )
    if SUMMARY_BREACH_PROB_COLUMN in summary:
        col3.metric(
            "Breach Prob",
            f"{summary[SUMMARY_BREACH_PROB_COLUMN].mean():.2%}",
            help=tooltip("breach probability"),
        )
    total_return = _overlay_total_return(summary)
    if total_return is not None:
        col4.metric(
            "Overlay Total",
            f"{total_return:.2%}",
            help=tooltip("overlay total"),
        )

    _render_explain_results(summary=summary, manifest_data=manifest_data, xlsx=xlsx)
    _render_comparison_panel(summary=summary, manifest_data=manifest_data, xlsx=xlsx)

    if "Config" in summary.columns:
        config_options = summary["Config"].unique().tolist()
        agents = st.sidebar.multiselect("Agents", config_options, config_options)
    else:
        if summary.index.name:
            agent_options = summary.index.tolist()
        else:
            agent_options = summary.index.tolist() if len(summary.index) > 0 else ["All"]
        agents = st.sidebar.multiselect("Agents", agent_options, agent_options)
    st.sidebar.number_input("Risk-free rate", value=0.0)
    auto = st.sidebar.checkbox("Auto-refresh")
    interval = st.sidebar.number_input("Refresh every (s)", 5, 300, 60)

    tab_names = list(PLOTS) + ["Diagnostics"]
    tabs = st.tabs(tab_names)

    for name, tab in zip(tab_names[:-1], tabs[:-1]):
        fn = _get_plot_fn(PLOTS[name])
        with tab:
            if name == "Headline":
                st.plotly_chart(fn(summary), use_container_width=True)
            elif paths is not None:
                sub_paths = paths[agents].iloc[:, :months]
                st.plotly_chart(fn(sub_paths), use_container_width=True)

    with tabs[-1]:
        st.dataframe(summary)

    # Export buttons
    col1, col2, col3 = st.columns(3)

    with col1:
        # PNG export with error handling
        try:
            render_png_download(
                st,
                key="results_headline_png",
                label="Download PNG",
                fig=_get_plot_fn(PLOTS["Headline"])(summary),
                file_name="risk_return.png",
            )
        except RuntimeError as e:
            if "kaleido" in str(e).lower() or "chrome" in str(e).lower():
                st.warning(
                    "📷 PNG export requires Kaleido or Chrome/Chromium. Install via `pip install kaleido` or `sudo apt-get install -y chromium-browser`"
                )
                st.info(
                    "💡 Tip: Use browser screenshot or install Kaleido (preferred) or Chrome for PNG exports"
                )
            else:
                st.error(f"PNG export error: {e}")

    with col2:
        # Excel download
        with open(xlsx, "rb") as fh:
            st.download_button("Download XLSX", fh, file_name=Path(xlsx).name)

    with col3:
        # Export packet button
        def _render_packet_downloads(paths: tuple[str, str]) -> None:
            pptx_path, excel_path = paths
            st.success("✅ Export packet created!")
            with open(pptx_path, "rb") as pptx_file:
                st.download_button(
                    "📋 Download PowerPoint",
                    pptx_file.read(),
                    file_name=Path(pptx_path).name,
                    mime="application/vnd.openxmlformats-officedocument.presentationml.presentation",
                )
            with open(excel_path, "rb") as excel_file:
                st.download_button(
                    "📊 Download Enhanced Excel",
                    excel_file.read(),
                    file_name=Path(excel_path).name,
                    mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                )

        def _packet_args() -> dict[str, object]:
            sys.path.append(str(Path(__file__).parents[1]))
            fig = _get_plot_fn(PLOTS["Headline"])(summary)
            raw_returns_dict = {SUMMARY_SHEET_NAME: summary}
            inputs_dict = {
                "Data_Source": xlsx,
                "Generated_At": str(pd.Timestamp.now()),
                "Summary_Rows": len(summary),
            }
            base_name = f"committee_packet_{int(time.time())}"

            prev_manifest_data = None
            prev_summary_df = None
            prev_manifest_path = None
            if manifest_data:
                prev_ref = manifest_data.get("previous_run")
                if isinstance(prev_ref, str):
                    candidate = Path(prev_ref)
                    if candidate.exists():
                        prev_manifest_path = candidate
            if prev_manifest_path is not None:
                try:
                    prev_manifest_data = json.loads(prev_manifest_path.read_text())
                    prev_out = (
                        prev_manifest_data.get("cli_args", {}).get("output")
                        if isinstance(prev_manifest_data, dict)
                        else None
                    )
                    if prev_out and Path(prev_out).exists():
                        prev_summary_df = pd.read_excel(prev_out, sheet_name=SUMMARY_SHEET_NAME)
                except Exception:
                    prev_manifest_data = None
                    prev_summary_df = None

            stress_delta_df = None
            try:
                stress_delta_df = pd.read_excel(xlsx, sheet_name="StressDelta")
                if stress_delta_df.empty:
                    stress_delta_df = None
            except (FileNotFoundError, PermissionError, ValueError, OSError):
                stress_delta_df = None

            return {
                "figs": [fig],
                "summary_df": summary,
                "raw_returns_dict": raw_returns_dict,
                "inputs_dict": inputs_dict,
                "base_filename": base_name,
                "manifest": manifest_data,
                "prev_summary_df": prev_summary_df,
                "prev_manifest": prev_manifest_data,
                "stress_delta_df": stress_delta_df,
            }

        try:
            from pa_core.reporting.export_packet import create_export_packet_async

            async def _create_packet_async() -> tuple[str, str]:
                return await create_export_packet_async(**_packet_args())

            render_async_export_button(
                st,
                key="results_committee_packet",
                label="📦 Export Committee Packet",
                factory=_create_packet_async,
                on_ready=_render_packet_downloads,
                pending_message="Creating export packet...",
            )
        except RuntimeError as e:
            if (
                "kaleido" in str(e).lower()
                or "chrome" in str(e).lower()
                or "chromium" in str(e).lower()
            ):
                st.error(
                    "📷 Export packet requires Kaleido or Chrome/Chromium for chart generation."
                )
                st.info(
                    "Install with: `pip install kaleido` or `sudo apt-get install chromium-browser`"
                )
            else:
                st.error(f"Export packet failed: {e}")
        except Exception as e:
            st.error(f"Unexpected error creating export packet: {e}")
            st.info("Please check your environment and try individual exports instead.")

    if auto:
        time.sleep(interval)
        st.rerun()


if __name__ == "__main__":
    main()
